 return <><Field label={label}><select aria-label={label} value={other?'__other__':value} onChange={e=>{const custom=e.target.value==='__other__';setOther(custom);onChange(custom?'':e.target.value)}}><option value="">请选择</option>{options.map(v=><option key={v}>{v}</option>)}<option value="__other__">其他</option></select></Field>{other&&<Field label={'其他'+label}><input aria-label={'其他'+label} value={value} maxLength={100} placeholder="请输入具体内容" onChange={e=>onChange(e.target.value)}/></Field>}</>;
